INSERT INTO `locales_creature_text` (`entry`, `textGroup`, `id`, `text_loc1`, `text_loc2`, `text_loc3`, `text_loc4`, `text_loc5`, `text_loc6`, `text_loc7`, `text_loc8`, `text_loc9`, `text_loc10`) VALUES
	(60491, 0, 0, '내 분노를 보여주마!', 'MA FUREUR SE DÉCHAÎNE !!', 'Meine Wut wurde ENTFESSELT!', '我的怒火无人能挡！！', '釋放我的怒火!', '¡MI FURIA NO TIENE LÍMITES!', '¡MI FURIA NO TIENE LÍMITES!', 'Моя ярость безгранична!', 'Minha fúria foi LIBERADA!', 'LA MIA FURIA SI SCATENA!!!'),
	(60491, 1, 1, '네 분노로 날 살찌워라!', 'Nourrissez-moi de votre COLÈRE !', 'Nährt mich mit Eurem ZORN!', '让我痛饮你的愤怒！', '獻上你的怒火吧!', '¡Fortalecedme con vuestra rabia!', '¡Fortalézcanme con su rabia!', 'Ваш гнев – моя пища!', 'Alimente-me com sua IRA!', 'Sfamatemi con la vostra rabbia!'),
	(54567, 0, 0, '고대의 적과 우리 사이의 전쟁은 아직 끝나지 않은 것 같군.', 'Je crains que notre guerre contre nos anciens ennemis soit loin d’être terminée.', 'Ich fürchte, dass der Krieg gegen unsere uralten Feinde noch lange nicht vorüber ist.', '恐怕我们对抗远古敌人的战斗还远未结束。', '我擔心這場對抗我們古老敵人的戰爭離結束還很遠。', 'Me temo que la guerra contra nuestros antiguos enemigos acaba de empezar.', 'Me temo que la guerra contra nuestros antiguos enemigos acaba de empezar.', 'Я боюсь, что война с нашим древним врагом все еще не окончена.', 'Temo que a guerra contra nossos antigos inimigos ainda esteja longe de acabar.', 'Temo che la guerra contro i nostri antichi nemici sia tutt\'altro che finita.'),
	(54568, 0, 0, '고대의 적과 우리 사이의 전쟁은 아직 끝나지 않은 것 같군.', 'Je crains que notre guerre contre nos anciens ennemis soit loin d’être terminée.', 'Ich fürchte, dass der Krieg gegen unsere uralten Feinde noch lange nicht vorüber ist.', '恐怕我们对抗远古敌人的战斗还远未结束。', '我擔心這場對抗我們古老敵人的戰爭離結束還很遠。', 'Me temo que la guerra contra nuestros antiguos enemigos acaba de empezar.', 'Me temo que la guerra contra nuestros antiguos enemigos acaba de empezar.', 'Я боюсь, что война с нашим древним врагом все еще не окончена.', 'Temo que a guerra contra nossos antigos inimigos ainda esteja longe de acabar.', 'Temo che la guerra contro i nostri antichi nemici sia tutt\'altro che finita.'),
	(54586, 0, 0, '당신만큼 출중한 수련생은 처음 봅니다. 다른 이들에게도 이야기해야겠습니다.', 'Je n’ai jamais vu de recrue avec votre talent. Je dois le dire aux autres.', 'Noch nie habe ich einen so fähigen Lehrling wie Euch gesehen. Ich muss den anderen davon berichten.', '我从没见过像你这么厉害的学徒。我得告诉其他人去。', '我從沒見過擁有你這種技巧的受訓弟子。我得跟其他人講。', 'Alumnos con habilidades como las tuyas no se ven todos los días. Tengo que contárselo a los demás.', 'Alumnos con habilidades como las tuyas no se ven todos los días. Tengo que contárselo a los demás.', 'Мне никогда не приходилось видеть таких способных новичков. Я должен рассказать остальным.', 'Eu nunca vi um aprendiz com habilidades como as suas. Preciso informar os outros.', 'Non ho mai visto nessun allievo abile quanto te. Devo dirlo agli altri.'),
	(54586, 1, 0, '당신 실력에 미치려면 아직 멀었군. 패배를 인정하겠소.', 'Vos compétences surpassent les miennes. L’humble combattant sait reconnaître une défaite.', 'Meine Fähigkeiten sind den Euren unterlegen. Ich gebe mich geschlagen.', '我打不过你。我认输了。', '我不是你的對手，我認輸。', 'Mis habilidades no pueden compararse con las tuyas. Asumo mi derrota.', 'Mis habilidades no pueden compararse con las tuyas. Asumo mi derrota.', 'Моему искусству не сравниться с твоим. Я признаю поражение.', 'Minhas habilidades não são suficientes contra você. Admito a derrota.', 'La mia abilità non è paragonabile alla tua. Ammetto la sconfitta.'),
	(54586, 2, 0, '고맙습니다. 더욱 부지런히 수련하기로 다짐하는 계기가 됐습니다.', 'Merci de m’avoir rappelé que je dois m’entraîner avec plus de discipline.', 'Danke, dass Ihr mich daran erinnert habt, fleißiger trainieren zu müssen.', '多谢你的指点，我必须更加努力地修炼才行。', '謝謝你提醒了我應該更加勤奮地鍛鍊自己。', 'Gracias por recordarme que tengo que entrenar con más diligencia.', 'Gracias por recordarme que tengo que entrenar con más diligencia.', 'Спасибо за напоминание о том, что нужно тренироваться усерднее.', 'Agradeço por me lembrar de que preciso treinar com mais diligência.', 'Grazie per avermi ricordato che devo allenarmi più diligentemente.'),
	(54586, 3, 0, '좋은 싸움이었소. 고맙소.', 'Ce fut un beau combat. Merci.', 'Das war ein guter Kampf. Danke.', '真是场痛快的战斗。谢谢你。', '這是場精采的比試。多謝指教。', 'Buena pelea. Gracias.', 'Buena pelea. Gracias.', 'Это был хороший бой. Благодарю тебя.', 'Foi uma boa luta. Obrigado.', 'È stato un bel combattimento. Grazie.'),
	(54586, 4, 0, '당신은 훌륭한 대련 상대군요.', 'Ce fut un combat honorable.', 'Ihr seid ein ehrenhafter Gegner.', '你是一位可敬的对手。', '你是個可敬的對手。', 'Es un honor ser tu oponente.', 'Es un honor ser tu oponente.', 'Ты славный противник.', '"Você é $gum:uma; oponente honorável."', 'Hai rappresentato una degna sfida.'),
	(54586, 5, 0, '명예롭게 싸우는군요, 친구.', 'Vous combattez avec honneur.', 'Ihr kämpft ehrenvoll.', '你赢得光明正大，朋友。', '你贏得正大光明，朋友。', 'Has luchado con honor.', 'Has luchado con honor.', 'Достойный поединок, друг.', '"Você luta de forma honorável, $gamigo:amiga;."', 'Combatti con onore.'),
	(54587, 0, 0, '당신만큼 출중한 수련생은 처음 봅니다. 다른 이들에게도 이야기해야겠습니다.', 'Je n’ai jamais vu de recrue avec votre talent. Je dois le dire aux autres.', 'Noch nie habe ich einen so fähigen Lehrling wie Euch gesehen. Ich muss den anderen davon berichten.', '我从没见过像你这么厉害的学徒。我得告诉其他人去。', '我從沒見過擁有你這種技巧的受訓弟子。我得跟其他人講。', 'Alumnos con habilidades como las tuyas no se ven todos los días. Tengo que contárselo a los demás.', 'Alumnos con habilidades como las tuyas no se ven todos los días. Tengo que contárselo a los demás.', 'Мне никогда не приходилось видеть таких способных новичков. Я должен рассказать остальным.', 'Eu nunca vi um aprendiz com habilidades como as suas. Preciso informar os outros.', 'Non ho mai visto nessun allievo abile quanto te. Devo dirlo agli altri.'),
	(54587, 0, 1, '', 'Vos compétences surpassent les miennes. L’humble combattant sait reconnaître une défaite.', '', '', '', 'Sus habilidades superan la mía. El humilde boxeador sabe una derrota.', 'Sus habilidades superan la mía. El humilde boxeador sabe una derrota.', '', '', 'Le vostre abilità di superare la mia. L\'umile combattente sa una sconfitta.'),
	(54587, 0, 2, '', 'Merci de m’avoir rappelé que je dois m’entraîner avec plus de discipline.', '', '', '', 'Gracias por recordarme que tengo que entrenar con más disciplina usted.', 'Gracias por recordarme que tengo que entrenar con más disciplina usted.', '', '', 'Grazie per avermi ricordato che devo allenarmi con più disciplina voi.'),
	(54587, 0, 3, '', 'Ce fut un combat honorable.', '', '', '', 'Fue una lucha honorable.', 'Fue una lucha honorable.', '', '', 'E \'stata una lotta onorevole.'),
	(54587, 0, 4, '', 'Vous êtes un honorable adversaire.', '', '', '', 'Usted es un oponente honorable.', 'Usted es un oponente honorable.', '', '', 'Tu sei un avversario onorevole.'),
	(54587, 0, 5, '', 'Vous vous êtes bien battu, mon ami.', '', '', '', 'Has luchado bien, amigo mío.', 'Has luchado bien, amigo mío.', '', '', 'Avete combattuto bene, amico mio.'),
	(54587, 0, 6, '', 'Vous avez bien combattu. Je dois prendre exemple sur vous, à l’avenir.', '', '', '', 'Has luchado bien. Tengo que tomar su ejemplo en el futuro.', 'Has luchado bien. Tengo que tomar su ejemplo en el futuro.', '', '', 'Avete combattuto bene. Devo prendere il tuo esempio, in futuro.'),
	(54587, 0, 7, '', 'Vos compétences sont trop grandes. J\'abandonne.', '', '', '', 'Sus habilidades son demasiado grandes. Me doy por vencido.', 'Sus habilidades son demasiado grandes. Me doy por vencido.', '', '', 'Le vostre abilità sono troppo grandi. Mi arrendo.'),
	(54611, 5, 0, '잘 싸우셨습니다. 샹 사부님께서 기뻐하실 겁니다.', 'Vous avez bien combattu. Maître Shang sera ravi.', 'Gut gekämpft. Meister Shang wird zufrieden sein.', '打得漂亮。尚师父会很高兴的。', '打得好。尚羲大師會很高興的。', 'Buen combate. El maestro Shang se alegrará mucho.', 'Buen combate. El maestro Shang se alegrará mucho.', 'Прекрасный бой. Мастер Шан будет доволен.', 'Boa luta. O Mestre Shang ficará satisfeito.', 'Ottimo combattimento. Il Maestro Shang sarà compiaciuto.'),
	(54611, 4, 0, '당신에게 진 것은 영광입니다.', 'C’est un honneur d’être vaincu par vous.', 'Es war eine Ehre, von Euch besiegt worden zu sein.', '被你击败是一种荣誉。', '敗在你手下是我的榮幸。', 'Ha sido un honor que me hayas derrotado.', 'Ha sido un honor que me hayas derrotado.', 'Быть побежденным тобой – большая честь.', 'Foi uma honra ser derrotado por você.', 'È stato un onore essere sconfitto da te.'),
	(54611, 3, 0, '제가 아직 수련이 부족한 것 같습니다. 가르침, 감사합니다.', 'Le pandaren humble sait reconnaître quand son apprentissage n’est pas terminé. Merci pour cette leçon.', 'Es scheint, als ob ich noch mehr trainieren müsste. Ich danke Euch für die Lehrstunde.', '看来我还需要更多的练习。感谢你的教诲。', '看來我還得接受更多的訓練。多謝指教。', 'Parece que tengo que entrenar más. Gracias por la lección.', 'Parece que tengo que entrenar más. Gracias por la lección.', 'Похоже, мне придется еще как следует потренироваться. Благодарю за урок.', 'Parece que tenho muito o que treinar. Agradeço a lição.', 'A quanto pare devo allenarmi di più. Grazie per la lezione.'),
	(54611, 2, 0, '그 실력에 경의를 표합니다. 정정당당히 저를 이기셨습니다.', 'Je m’incline devant vos compétences. Vous m’avez vaincu avec honneur.', 'Ich verbeuge mich vor Eurer Leistung. Ihr habt mich fair geschlagen.', '我打不过你。你赢得光明正大。', '你的技巧令人欽佩。你堂堂正正打敗了我。', 'Me inclino ante tus habilidades. Me has superado en buena lid.', 'Me inclino ante tus habilidades. Me has superado en buena lid.', 'Я преклоняюсь перед твоим мастерством. Я уступил в честном бою.', 'Curvo-me perante sua habilidade. Você me superou numa luta justa.', 'Mi inchino alla tua abilità. Mi hai battuto con onore.'),
	(54611, 0, 0, '도전자가 다가오는군요.', 'Un adversaire approche.', '$GEin Herausforderer:Eine Herausforderin; nähert sich.', '有挑战者过来了。', '一名挑戰者接近了。', 'Se acerca $gun:una; contendiente.', 'Se acerca $gun:una; contendiente.', 'А вот и мой соперник.', '$gUm:Uma; desafiante se aproxima.', 'Ecco arrivare $guno:una; sfidante.'),
	(54611, 1, 0, '그 실력에 경의를 표합니다. 정정당당히 저를 이기셨습니다.', 'Je m’incline devant vos compétences. Vous m’avez vaincu avec honneur.', 'Ich verbeuge mich vor Eurer Leistung. Ihr habt mich fair geschlagen.', '我打不过你。你赢得光明正大。', '你的技巧令人欽佩。你堂堂正正打敗了我。', 'Me inclino ante tus habilidades. Me has superado en buena lid.', 'Me inclino ante tus habilidades. Me has superado en buena lid.', 'Я преклоняюсь перед твоим мастерством. Я уступил в честном бою.', 'Curvo-me perante sua habilidade. Você me superou numa luta justa.', 'Mi inchino alla tua abilità. Mi hai battuto con onore.'),
	(54786, 0, 0, '잘 왔네, 후오. 모두 자네의 온기를 그리워했다네.', 'Bienvenue, Huo. Votre chaleur a manqué à notre peuple.', 'Willkommen, Huo. Das Volk hat Eure Wärme vermisst.', '欢迎你，燧焰。这里的人民想念你的温暖。', '歡迎，火靈。大家非常懷念你的溫暖。', 'Bienvenido, Huo. El pueblo echaba de menos tu calidez.', 'Bienvenido, Huo. El pueblo echaba de menos tu calidez.', 'Добро пожаловать, Хо. Наш народ соскучился по твоему теплу.', 'Bem-vindo, Huo. Nós sentimos falta do seu calor.', 'Benvenuto, Huo. Al popolo è mancato il tuo calore.'),
	(54855, 0, 0, '잘 왔네, 후오. 모두 자네의 온기를 그리워했다네.', 'Bienvenue, Huo. Votre chaleur a manqué à notre peuple.', 'Willkommen, Huo. Das Volk hat Eure Wärme vermisst.', '欢迎你，燧焰。这里的人民想念你的温暖。', '歡迎，火靈。大家非常懷念你的溫暖。', 'Bienvenido, Huo. El pueblo echaba de menos tu calidez.', 'Bienvenido, Huo. El pueblo echaba de menos tu calidez.', 'Добро пожаловать, Хо. Наш народ соскучился по твоему теплу.', 'Bem-vindo, Huo. Nós sentimos falta do seu calor.', 'Benvenuto, Huo. Al popolo è mancato il tuo calore.'),
	(54943, 0, 0, '잘 왔네, 후오. 모두 자네의 온기를 그리워했다네.', 'Bienvenue, Huo. Votre chaleur a manqué à notre peuple.', 'Willkommen, Huo. Das Volk hat Eure Wärme vermisst.', '欢迎你，燧焰。这里的人民想念你的温暖。', '歡迎，火靈。大家非常懷念你的溫暖。', 'Bienvenido, Huo. El pueblo echaba de menos tu calidez.', 'Bienvenido, Huo. El pueblo echaba de menos tu calidez.', 'Добро пожаловать, Хо. Наш народ соскучился по твоему теплу.', 'Bem-vindo, Huo. Nós sentimos falta do seu calor.', 'Benvenuto, Huo. Al popolo è mancato il tuo calore.'),
	(57712, 0, 0, '잘 왔네, 후오. 모두 자네의 온기를 그리워했다네.', 'Bienvenue, Huo. Votre chaleur a manqué à notre peuple.', 'Willkommen, Huo. Das Volk hat Eure Wärme vermisst.', '欢迎你，燧焰。这里的人民想念你的温暖。', '歡迎，火靈。大家非常懷念你的溫暖。', 'Bienvenido, Huo. El pueblo echaba de menos tu calidez.', 'Bienvenido, Huo. El pueblo echaba de menos tu calidez.', 'Добро пожаловать, Хо. Наш народ соскучился по твоему теплу.', 'Bem-vindo, Huo. Nós sentimos falta do seu calor.', 'Benvenuto, Huo. Al popolo è mancato il tuo calore.'),
	(60176, 0, 0, '불의 정령이 화가 났습니다. 지금 제단에 들어가면 위험합니다...', 'L’esprit du feu est en colère. Il est dangereux d’entrer dans le sanctuaire en ce moment...', 'Der Feuergeist ist aufgebracht. Es wäre gefährlich, den Tempel jetzt zu betreten...', '上古火灵十分烦躁。现在进入神龛是很危险的……', '火靈十分生氣。現在進入廟裡會很危險...', 'El espíritu del fuego está alterado. Es peligroso entrar en el santuario ahora mismo...', 'El espíritu del fuego está alterado. Es peligroso entrar en el santuario ahora mismo...', 'Дух огня расстроен. Сейчас опасно входить в святилище...', 'O espírito de fogo está irritado. É perigoso entrar no santuário agora...', 'Lo Spirito del Fuoco è turbato. In questo momento entrare nel santuario è pericoloso...'),
	(60183, 0, 0, '실력이 대단하오. 졌소.', 'Vos compétences sont tellement supérieures. Je m’incline.', 'Euer Können ist überwältigend. Ich ergebe mich.', '你太厉害了。我认输。', '你的技巧太好了，我投降。', 'Tus habilidades me superan. Me rindo.', 'Tus habilidades me superan. Me rindo.', 'Твое мастерство не вызывает сомнений. Я сдаюсь.', 'Sua habilidade é demais para mim. Eu me rendo.', 'La tua abilità è superiore. Mi arrendo.'),
	(60248, 0, 0, '저게... 저게 후오요?', 'Est-ce… Est-ce Huo ?', 'Ist das... ist das Huo?', '那……那不是燧焰吗？', '那是...那是霍嗎?', '¿Ese es... Huo?', '¿Ese es... Huo?', 'Это... это Хо?', 'Este é... Este é Huo?', 'Quello... quello è Huo?'),
	(60253, 0, 0, '저게... 저게 후오요?', 'Est-ce… Est-ce Huo ?', 'Ist das... ist das Huo?', '那……那不是燧焰吗？', '那是...那是霍嗎?', '¿Ese es... Huo?', '¿Ese es... Huo?', 'Это... это Хо?', 'Este é... Este é Huo?', 'Quello... quello è Huo?'),
	(54611, 6, 0, '잘 싸우셨습니다. 샹 사부님께서 기뻐하실 겁니다.', 'Vous avez bien combattu. Maître Shang sera ravi.', 'Gut gekämpft. Meister Shang wird zufrieden sein.', '打得漂亮。尚师父会很高兴的。', '打得好。尚羲大師會很高興的。', 'Buen combate. El maestro Shang se alegrará mucho.', 'Buen combate. El maestro Shang se alegrará mucho.', 'Прекрасный бой. Мастер Шан будет доволен.', 'Boa luta. O Mestre Shang ficará satisfeito.', 'Ottimo combattimento. Il Maestro Shang sarà compiaciuto.'),
	(54587, 7, 0, '실력이 대단하오. 졌소.', 'Vos compétences sont tellement supérieures. Je m’incline.', 'Euer Können ist überwältigend. Ich ergebe mich.', '你太厉害了。我认输。', '你的技巧太好了，我投降。', 'Tus habilidades me superan. Me rindo.', 'Tus habilidades me superan. Me rindo.', 'Твое мастерство не вызывает сомнений. Я сдаюсь.', 'Sua habilidade é demais para mim. Eu me rendo.', 'La tua abilità è superiore. Mi arrendo.'),
	(54587, 5, 0, '명예롭게 싸우는군요, 친구.', 'Vous combattez avec honneur.', 'Ihr kämpft ehrenvoll.', '你赢得光明正大，朋友。', '你贏得正大光明，朋友。', 'Has luchado con honor.', 'Has luchado con honor.', 'Достойный поединок, друг.', '"Você luta de forma honorável, $gamigo:amiga;."', 'Combatti con onore.'),
	(54587, 6, 0, '잘 싸우셨습니다. 나중에 또 한 수 가르쳐 주십시오.', 'Vous avez bien combattu. Je dois prendre exemple sur vous, à l’avenir.', 'Ihr habt gut gekämpft. Ich werde fortan noch viel von Euch lernen müssen.', '你很会战斗。我以后一定得好好向你学习。', '你打得太好了，未來我一定要多跟你學習。', 'Has combatido bien. Debo aprender más de ti en el futuro.', 'Has combatido bien. Debo aprender más de ti en el futuro.', 'Прекрасный бой. Мне можно будет многому у тебя научиться.', 'Você lutou bem. Preciso aprender mais com você no futuro.', 'Hai combattuto bene. In futuro, dovrò imparare molto da te.'),
	(54587, 4, 0, '당신은 훌륭한 대련 상대군요.', 'Ce fut un combat honorable.', 'Ihr seid ein ehrenhafter Gegner.', '你是一位可敬的对手。', '你是個可敬的對手。', 'Es un honor ser tu oponente.', 'Es un honor ser tu oponente.', 'Ты славный противник.', '"Você é $gum:uma; oponente honorável."', 'Hai rappresentato una degna sfida.'),
	(54587, 3, 0, '좋은 싸움이었소. 고맙소.', 'Ce fut un beau combat. Merci.', 'Das war ein guter Kampf. Danke.', '真是场痛快的战斗。谢谢你。', '這是場精采的比試。多謝指教。', 'Buena pelea. Gracias.', 'Buena pelea. Gracias.', 'Это был хороший бой. Благодарю тебя.', 'Foi uma boa luta. Obrigado.', 'È stato un bel combattimento. Grazie.'),
	(54587, 2, 0, '고맙습니다. 더욱 부지런히 수련하기로 다짐하는 계기가 됐습니다.', 'Merci de m’avoir rappelé que je dois m’entraîner avec plus de discipline.', 'Danke, dass Ihr mich daran erinnert habt, fleißiger trainieren zu müssen.', '多谢你的指点，我必须更加努力地修炼才行。', '謝謝你提醒了我應該更加勤奮地鍛鍊自己。', 'Gracias por recordarme que tengo que entrenar con más diligencia.', 'Gracias por recordarme que tengo que entrenar con más diligencia.', 'Спасибо за напоминание о том, что нужно тренироваться усерднее.', 'Agradeço por me lembrar de que preciso treinar com mais diligência.', 'Grazie per avermi ricordato che devo allenarmi più diligentemente.'),
	(54587, 1, 0, '당신 실력에 미치려면 아직 멀었군. 패배를 인정하겠소.', 'Vos compétences surpassent les miennes. L’humble combattant sait reconnaître une défaite.', 'Meine Fähigkeiten sind den Euren unterlegen. Ich gebe mich geschlagen.', '我打不过你。我认输了。', '我不是你的對手，我認輸。', 'Mis habilidades no pueden compararse con las tuyas. Asumo mi derrota.', 'Mis habilidades no pueden compararse con las tuyas. Asumo mi derrota.', 'Моему искусству не сравниться с твоим. Я признаю поражение.', 'Minhas habilidades não são suficientes contra você. Admito a derrota.', 'La mia abilità non è paragonabile alla tua. Ammetto la sconfitta.'),
	(65471, 0, 0, '당신만큼 출중한 수련생은 처음 봅니다. 다른 이들에게도 이야기해야겠습니다.', 'Je n’ai jamais vu de recrue avec votre talent. Je dois le dire aux autres.', 'Noch nie habe ich einen so fähigen Lehrling wie Euch gesehen. Ich muss den anderen davon berichten.', '我从没见过像你这么厉害的学徒。我得告诉其他人去。', '我從沒見過擁有你這種技巧的受訓弟子。我得跟其他人講。', 'Alumnos con habilidades como las tuyas no se ven todos los días. Tengo que contárselo a los demás.', 'Alumnos con habilidades como las tuyas no se ven todos los días. Tengo que contárselo a los demás.', 'Мне никогда не приходилось видеть таких способных новичков. Я должен рассказать остальным.', 'Eu nunca vi um aprendiz com habilidades como as suas. Preciso informar os outros.', 'Non ho mai visto nessun allievo abile quanto te. Devo dirlo agli altri.'),
