	(3974, 0, 0, NULL, NULL, 'Lasst die Hunde los!', NULL, NULL, NULL, NULL, NULL, NULL, NULL),
	(3975, 0, 0, '이단자들! 성스러운 칼을 받아라!', 'Des infidèles ! Ils doivent être purifiés !', 'Ungläubige! Sie müssen geläutert werden!', '异教徒， 净化他们！', '異教徒!淨化他們!', '¡Infieles! ¡Hay que purificarlos!', '¡Infieles! ¡Hay que purificarlos!', 'Нечестивцы! Да покарает их Свет!', 'Infiéis! Eles precisam ser purificados!', 'Infedeli! Devono essere purificati!'),
	(3975, 1, 0, '빛의 검을 받아라!', 'Lames de lumière !', 'Klingen des Lichts!', '光明之刃！', '聖光之刃!', '¡Espadas de luz!', '¡Espadas de luz!', 'Клинки света!', 'Espadas da luz!', 'Lame della luce!'),
	(3975, 2, 0, '빛이여, 힘을 주소서!', 'Lumière, donne-moi la force !', 'Licht, gib mir Kraft!', '圣光，赐予我力量吧！', '聖光，賜予我力量吧!', '¡Luz, dame tu fuerza!', '¡Luz, dame fuerza!', 'Свет, дай мне силу!', 'Luz, dai-me forças!', 'Luce, dammi forza!'),
