	(26861, 0, 0, '파괴할 수 없다.', 'Indestructible.', 'Unzerstörbar.', '不灭而不朽。', '堅不可催。', 'Indestructible.', 'Indestructible.', 'Несокрушим!', 'Indestrutível.', 'Indistruttibile.'),
	(26861, 1, 0, '파괴할 수 없다.', 'Indestructible.', 'Unzerstörbar.', '不灭而不朽。', '堅不可催。', 'Indestructible.', 'Indestructible.', 'Несокрушим!', 'Indestrutível.', 'Indistruttibile.'),
