	(39949, 0, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
	(39952, 0, 0, '너 박살내 버린다!', 'Moi écraser vous !', 'Ich werde Euch vernichten!', '我要撕碎你！', '我要撕碎你!', '¡Te machacaré!', '¡Te machacaré!', 'Я тебя раздавлю!', 'Vou te esmagar!', 'Io schiacciare te!'),
	(39952, 0, 1, '너 내가 죽인다!', 'Moi détruire ! Vous mourir !', 'Ich zerschmettern! Du sterben!', '你去死吧！', '你去死吧!', '¡Yo machacar! ¡Tú morir!', '¡Yo machacar! ¡Tú morir!', 'Моя бить! Твоя умирать!', 'Mim esmaga. Tu morre!', 'Io schiacciare, tu morire!'),
	(39952, 0, 2, '우어어!!! 나 $r 죽일거야!', 'Raaaaaaaaaaaaar !!! Moi détruire $r !', 'Raaar!!! Ich zerschmettern $R!', '啊！！！我要干掉$r！', '啊～～!!我要幹掉$r!', '¡¡Raaar!! ¡Yo machacar a $r!', '¡¡Raaar!! ¡Yo machacar a $r!', 'Рррааар! Моя убить |3-3($r)!', 'Raaar!!! Mim esmaga $r!', 'Raaar!!! Io schiacciare $R!'),
	(39952, 1, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
	(39957, 0, 0, '너 박살내 버린다!', 'Moi écraser vous !', 'Ich werde Euch vernichten!', '我要撕碎你！', '我要撕碎你!', '¡Te machacaré!', '¡Te machacaré!', 'Я тебя раздавлю!', 'Vou te esmagar!', 'Io schiacciare te!'),
